import torch
from transformers import BertTokenizer, BertForSequenceClassification

# Load the pre-trained model and tokenizer
model_name = "bert-base-uncased"
tokenizer = BertTokenizer.from_pretrained(model_name)
model = BertForSequenceClassification.from_pretrained(model_name, num_labels=2)

# Load the dataset
dataset = load_dataset("code_correction")

# Fine-tune the model on the dataset
model.train()
for epoch in range(num_epochs):
    for batch in dataset:
        input_ids = tokenizer(batch["code"], return_tensors="pt").input_ids
        labels = torch.tensor(batch["label"])
        outputs = model(input_ids, labels=labels)
        loss = outputs.loss
        loss.backward()
        optimizer.step()
        optimizer.zero_grad()

# Save the fine-tuned model
model.save_pretrained("code_correction_model")

# Load the fine-tuned model
model = BertForSequenceClassification.from_pretrained("code_correction_model")

# Correct the code
def correct_code(code):
    input_ids = tokenizer(code, return_tensors="pt").input_ids
    outputs = model(input_ids)
    predicted_label = torch.argmax(outputs.logits)
    if predicted_label == 1:
        return code
    else:
        return "Error: Syntax or logic error in code"

# Test the code correction system
code = "def add(x, y): return x + y"
corrected_code = correct_code(code)
