# Function to check if a number is prime
is_prime() {
    local num=$1
    if (( num <= 1 )); then
        return 1
    fi
    for (( i=2; i*i<=num; i++ )); do
        if (( num % i == 0 )); then
            return 1
        fi
    done
    return 0
}

# Function to find the largest prime factor
largest_prime_factor() {
    local num=$1
    local largest_factor=1
    local i=2

    while (( i*i <= num )); do
        if (( num % i == 0 )); then
            num=$((num / i))
            largest_factor=$i
        else
            ((i++))
        fi
    done

    if (( num > 1 )); then
        largest_factor=$num
    fi

    echo $largest_factor
}

