#!/bin/bash

# Function to check if a string is a palindrome
is_palindrome() {
    local str="$1"
    local len=${#str}
    local mid=$((len / 2))
    local i=0

    while [ $i -lt $mid ]; do
        if [ "${str:$i:1}" != "${str:$(($len - $i - 1)):1}" ]; then
            return 1 # Not a palindrome
        fi
        ((i++))
    done

    return 0 # Palindrome
}

# Function to find the longest palindromic substring
longest_palindrome() {
    local str="$1"
    local len=${#str}
    local max_len=1
    local start=0
    local i=0
    local j=0
    local k=0

    for ((i=0; i<$len; i++)); do
        for ((j=i; j<$len; j++)); do
            local substr=${str:i:j-i+1}
            if is_palindrome "$substr"; then
                local substr_len=${#substr}
                if ((substr_len > max_len)); then
                    max_len=$substr_len
                    start=$i
                fi
            fi
        done
    done

    echo "${str:start:max_len}"
}

