# Function to check if a string is a palindrome
is_palindrome() {
    local str="$1"
    local reversed_str=$(echo "$str" | rev)
    if [ "$str" == "$reversed_str" ]; then
        return 0
    else
        return 1
    fi
}

# Function to find the longest palindromic substring
longest_palindrome() {
    local str="$1"
    local max_length=0
    local longest_palindrome=""

    for ((i=0; i<${#str}; i++)); do
        for ((j=i+1; j<=${#str}; j++)); do
            local substring="${str:i:j-i}"
            if is_palindrome "$substring"; then
                local length=${#substring}
                if (( length > max_length )); then
                    max_length=$length
                    longest_palindrome="$substring"
                fi
            fi
        done
    done

    echo "$longest_palindrome"
}

# Read input from the user
read -p "Enter a string: " input_str

# Find the longest palindromic substring
