import java.util.*;
import java.math.BigInteger; 

public class Boss {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] a = new int[n + 1]; // Initialize array with size n + 1
        for (int i = 0; i < n - 1; i++) {
            int x = sc.nextInt();
            int y = sc.nextInt();
            a[x]++;
            a[y]++;
        }
        long ans = 1;
        for (int i = 1; i <= n; i++) {
            ans = ans * fact(a[i]) % 998244353; // Calculate factorial and take modulo
        }
        System.out.print(ans % 998244353); // Print final result
    }

    public static long fact(int a) {
        if (a == 0 || a == 1)
            return 1;
        return a * fact(a - 1) % 998244353; // Calculate factorial and take modulo
    }
}
```

