import java.util.Scanner;

public class Water3 {
    public static void main(String[] args) {
        Scanner cin = new Scanner(System.in);

        while (cin.hasNext()) {
            long n = cin.nextLong();
            long m = cin.nextLong();
            long k = cin.nextLong();
            long x = 1, y = 1;

            if (k < n) {
                x += k;
                k = 0;
            } else {
                x += (n - 1);
                k -= (n - 1);
            }

            if (k > 0) {
                long kDiv = k / (m - 1);
                x = n - kDiv + 1;

                if (k % (m - 1) != 0) {
                    x -= 1;
                    if (x % 2 == 0) {
                        y = 2 + k % (m - 1) - 1;
                    } else {
                        y = m - k % (m - 1) + 1;
                    }
                } else {
                    if (x % 2 == 0) {
                        y = m;
                    } else {
                        y = 2;
                    }
                }
            }

            System.out.println(x + " " + y);
        }
    }
}
