file_extension=".txt"

# Define the search term to look for in the files
search_term="example"

# Define the output file name
output_file="output.txt"

# Initialize an empty array to store the file names
file_names=()

# Loop through all the files in the directory
for file in "$directory"/*"$file_extension"; do
  # Check if the file exists
  if [ -f "$file" ]; then
    # Check if the search term is present in the file
    if grep -q "$search_term" "$file"; then
      # If the search term is present, add the file name to the array
      file_names+=("$file")
    fi
  fi
done

# Check if any files were found
