import openai
import sys

def generate_code(prompt, language, api_key):
    openai.api_key = api_key
    response = openai.Completion.create(
        engine="text-davinci-002",
        prompt=prompt,
        max_tokens=1024,
        n=1,
        stop=None,
        temperature=0.5,
    )
    code = response.choices[0].text.strip()
    if language == "java":
        code = "public class Main {\n" + code + "\n}"
    elif language == "python":
        code = "def main():\n" + code + "\nif __name__ == '__main__':\n    main()"
    elif language == "c++":
        code = "#include <iostream>\n\nint main() {\n" + code + "\n    return 0;\n}"
    return code

if __name__ == "__main__":
