class Solution {
    public int maxProfit(int[] prices) {
        int minPrice = Integer.MAX_VALUE;
        int maxProfit = 0;

        for (int price : prices) {
            if (price < minPrice) {
                minPrice = price;
            } else if (price - minPrice > maxProfit) {
                maxProfit = price - minPrice;
            }
        }

        return maxProfit;
    }
}

// Test case
public class Main {
    public static void main(String[] args) {
        Solution solution = new Solution();
        int[] prices = {7, 1, 5, 3, 6, 4};
        int maxProfit = solution.maxProfit(prices);
        System.out.println("Maximum profit: " + maxProfit);
    }
}

// Output:
// Maximum profit: 5

// Explanation:
// In this example, the maximum profit can be obtained by buying at a price of 1 and selling at a price of 6, resulting in a profit of 5. The code iterates through the prices array, keeping track of the minimum price encountered so far and updating the maximum profit whenever a higher profit is found. The final maximum profit is returned as the result.
