    public static void main(String[] args) {
        int[] nums = {1, 2, 3, 4, 5};
        int[] result = findEvenOddSums(nums);
        System.out.println("Even Sum: " + result[0]);
        System.out.println("Odd Sum: " + result[1]);
    }

    public static int[] findEvenOddSums(int[] nums) {
        int evenSum = 0;
        int oddSum = 0;

        for (int num : nums) {
            if (num % 2 == 0) {
                evenSum += num;
            } else {
                oddSum += num;
            }
        }

        return new int[]{evenSum, oddSum};
    }
}
