import java.util.ArrayList;

class Solution {
    public boolean areAlmostEqual(String s1, String s2) {
        if (s1.equals(s2))
            return true;
        ArrayList<Character> ts = new ArrayList<>();
        ArrayList<Character> ts1 = new ArrayList<>();
        int count = 0;
