            if (result < Integer.MIN_VALUE / 10 || (result == Integer.MIN_VALUE / 10 && digit < -8)) {
                return 0;
            }
            result = result * 10 + digit;
        }
        return result;
    }

    public static void main(String[] args) {
        int x = 123;
        int reversed = reverse(x);
        System.out.println("Reversed: " + reversed);
    }
}
```

