public class Problem1 {
    public static void main(String[] args) {
        int[] nums = {1, 2, 3, 4, 5};
        int k = 3;
        List<List<Integer>> result = findSubsets(nums, k);
        System.out.println(result);
    }

    public static List<List<Integer>> findSubsets(int[] nums, int k) {
        List<List<Integer>> result = new ArrayList<>();
        findSubsetsHelper(nums, k, 0, new ArrayList<>(), result);
        return result;
    }

    private static void findSubsetsHelper(int[] nums, int k, int index, List<Integer> current, List<List<Integer>> result) {
        if (current.size() == k) {
            result.add(new ArrayList<>(current));
            return;
        }

        for (int i = index; i < nums.length; i++) {
            current.add(nums[i]);
            findSubsetsHelper(nums, k, i + 1, current, result);
            current.remove(current.size() - 1);
        }
    }
}

