class Solution {
public:
    double average(vector<int>& salary) {
        int n = salary.size();
        int sum = 0;
        int Min = INT_MAX;
        int Max = INT_MIN;

        for (int i : salary) {
            Max = max(Max, i);
            Min = min(Min, i);
            sum += i;
        }

        sum -= (Min + Max);
        return static_cast<double>(sum) / (n - 2);
    }
};
