#include <iostream>
#include <vector>

int findMaxSum(const std::vector<int>& nums) {
    int maxSum = 0;
    int currentSum = 0;

    for (int num : nums) {
        currentSum += num;
        if (currentSum > maxSum) {
            maxSum = currentSum;
        }
        if (currentSum < 0) {
            currentSum = 0;
        }
    }

    return maxSum;
}

int main() {
    std::vector<int> nums = {1, -2, 3, 4, -1, 2, 1, -5, 4};
    int maxSum = findMaxSum(nums);
    std::cout << "Maximum sum: " << maxSum << std::endl;
    return 0;
}
```

This solution finds the maximum sum of a contiguous subarray within a given array of integers.

