```cpp
#include <vector>
#include <stack>

class Solution {
public:
    // Function to find the index of the next smaller number
    std::vector<int> nextSmallNumberIndex(const std::vector<int>& v) {
        int n = v.size();
        std::vector<int> ans(n);
        std::stack<int> s;
        s.push(-1);
        for (int i = n - 1; i >= 0; i--) {
            int num = v[i];
            while (!s.empty() && v[s.top()] >= num) {
                s.pop();
            }
            ans[i] = s.empty() ? -1 : s.top();
            s.push(i);
        }
        return ans;
    }
};
```

