class Solution {
public:
    int maxProfit(vector<int>& prices) {
        int n = prices.size();
        if (n == 0) return 0;

        int minPrice = prices[0];
        int maxProfit = 0;

        for (int i = 1; i < n; i++) {
            if (prices[i] < minPrice) {
                minPrice = prices[i];
            } else {
                maxProfit = max(maxProfit, prices[i] - minPrice);
            }
        }

        return maxProfit;
    }
};

// Time Complexity: O(n)
// Space Complexity: O(1)

// Explanation:
// The code uses a single pass approach to find the maximum profit that can be obtained by buying and selling a stock.
// It initializes the minimum price to the first element of the prices array and the maximum profit to 0.
// Then, it iterates through the prices array starting from the second element.
// If the current price is less than the minimum price, it updates the minimum price.
// Otherwise, it calculates the profit by subtracting the minimum price from the current price and updates the maximum profit if the calculated profit is greater than the current maximum profit.
// Finally, it returns the maximum profit.

// Example:
// Input: prices = [7,1,5,3,6,4]
// Output: 5
// Explanation: Buy on day 2 (price = 1) and sell on day 5 (price = 6), profit = 6-1 = 5.
// Note that buying on day 2 and selling on day 1 is not allowed because you must buy before you sell.

// Input: prices = [7,6,4,3,1]
// Output: 0
// Explanation: In this case, no transactions are done and the max profit = 0.

// Input: prices = [1,2,3,4,5]
// Output: 4
// Explanation: Buy on day 1 (price = 1) and sell on day 5 (price = 5), profit = 5-1 = 4.

// Input: prices = [7,6,4,3,1]
// Output: 0
// Explanation: In this case, no transactions are done and the max profit = 0.

// Input: prices = [1]
// Output: 0
// Explanation: In this case, no transactions are done and the max profit = 0.

// Input: prices = [1,2]
// Output: 1
// Explanation: Buy on day 1 (price = 1) and sell on day 2 (price = 2), profit = 2-1 = 1.

// Input: prices = [2,1]
// Output: 0
// Explanation: In this case, no transactions are done and the max profit = 0.

// Input: prices = [2,1,2]
// Output: 1
// Explanation: Buy on day 1 (price = 2) and sell on day 2 (price = 1), profit = 1-2 = -1. Then buy on day 2 (price = 1) and sell on day 3 (price = 2), profit = 2-1 = 1.

// Input: prices = [2,1,2,1,2]
// Output: 2
//

