#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    int shortestBridge(vector<vector<int>>& grid) {
        int n = grid.size();
        vector<vector<int>> vis(n, vector<int>(n, 0));
        queue<pair<int, int>> q;
        bool flag = false;

        // Find the first island and mark it with 2
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    dfs(i, j, grid, vis, q);
                    flag = true;
                    break;
                }
            }
            if (flag) break;
        }

        // Perform BFS to find the shortest bridge
        int ans = 0;
        while (!q.empty()) {
            int size = q.size();
            while (size--) {
                auto [row, col] = q.front();
                q.pop();

                for (int i = 0; i < 4; i++) {
                    int nrow = row + r[i];
                    int ncol = col + c[i];

                    if (nrow >= 0 && ncol >= 0 && nrow < n && ncol < n && vis[nrow][ncol] == 0) {
                        if (grid[nrow][ncol] == 1) {
                            return ans;
                        }
                        vis[nrow][ncol] = 1;
                        q.push({nrow, ncol});
                    }
                }
            }
            ans++;
        }

        return ans;
    }

private:
    int r[4] = {-1, 0, 1, 0};
    int c[4] = {0, 1, 0, -1};

