def maximumGap(nums):
    if len(nums) < 2:
        return 0

    # Find the maximum and minimum values in the array
    max_val = max(nums)
    min_val = min(nums)

    # Calculate the gap between each bucket
    gap = max(1, (max_val - min_val) // (len(nums) - 1))

    # Initialize the buckets
    buckets = [[] for _ in range((max_val - min_val) // gap + 1)]

    # Distribute the numbers into the buckets
    for num in nums:
        index = (num - min_val) // gap
        buckets[index].append(num)

    # Find the maximum gap between adjacent buckets
    max_gap = 0
    prev_max = min_val
    for bucket in buckets:
        if bucket:
            max_gap = max(max_gap, min(bucket) - prev_max)
            prev_max = max(bucket)

    return max_gap

