public:
    int minOperations(vector<int>& nums, int x) {
        int n = nums.size();
        int sum = 0;
        for (int num : nums) {
            sum += num;
        }
        int target = sum - x;
        if (target < 0) {
            return -1;
        }
        int left = 0;
        int right = 0;
        int maxLen = 0;
        int currSum = 0;
        while (right < n) {
            currSum += nums[right];
            while (currSum > target) {
                currSum -= nums[left];
                left++;
            }
            if (currSum == target) {
                maxLen = max(maxLen, right - left + 1);
            }
            right++;
        }
        return maxLen == 0 ? -1 : n - maxLen;
    }
};

