public:
    vector<int> closestPrimes(int left, int right) {
        // marks all prime numbers from 2 to right using sieve algorithm
        vector<int> nums(right + 1, 1);
        for (int i = 2; i * i <= right; i++) {
            if (nums[i] == 1) {
                for (int j = i * i; j <= right; j += i)
                    nums[j] = 0;
            }
        }

        // storing all prime numbers between left and right
        vector<int> prime;
        for (int i = max(2, left); i <= right; i++) {
            if (nums[i] == 1)
                prime.push_back(i);
        }

