## Example Solution
Here's an example of a solution in C++:

```cpp
#include <iostream>
#include <vector>

class Solution {
public:
    bool checkValidGrid(std::vector<std::vector<int>>& grid) {
        if (grid[0][0] != 0) {
            return false;
        }

        int n = grid.size();
        std::vector<std::vector<int>> directions = {
            {-2, 1}, {-2, -1}, {2, -1}, {2, 1}, {1, 2}, {-1, 2}, {-1, -2}, {1, -2}
        };

        std::vector<std::vector<bool>> visited(n, std::vector<bool>(n, false));
        visited[0][0] = true;

        return dfs(grid, visited, directions, 0, 0, 1);
    }

private:
    bool dfs(std::vector<std::vector<int>>& grid, std::vector<std::vector<bool>>& visited, std::vector<std::vector<int>>& directions, int row, int col, int num) {
        int n = grid.size();

        if (num == n * n) {
            return true;
        }

        for (const auto& dir : directions) {
            int newRow = row + dir[0];
            int newCol = col + dir[1];

            if (newRow >= 0 && newRow < n && newCol >= 0 && newCol < n && grid[newRow][newCol] == num && !visited[newRow][newCol]) {
                visited[newRow][newCol] = true;
                if (dfs(grid, visited, directions, newRow, newCol, num + 1)) {
                    return true;
                }
                visited[newRow][newCol] = false;
            }
        }

        return false;
    }
};

int main() {
    Solution solution;
    std::vector<std::vector<int>> grid = {
        {0, 11, 16, 5, 20},
        {17, 4, 19, 10, 15},
        {12, 1, 8, 21, 6},
        {3, 18, 23, 14, 9},
        {24, 13, 2, 7, 22}
    };

    bool result = solution.checkValidGrid(grid);
    std::cout << "Result: " << (result ? "true" : "false") << std::endl;

    return 0;
}
```

This example demonstrates a solution to a coding problem using depth-first search (DFS) in C++. The `checkValidGrid` function checks if a given grid is a valid knight's tour. The `dfs` function is a helper function that performs the DFS traversal.

