## Example Solution
Here's an example of a solution in C++:

```cpp
#include <iostream>
#include <vector>
#include <algorithm>

class Solution {
public:
    std::string longestCommonPrefix(std::vector<std::string>& strs) {
        if (strs.empty()) {
            return "";
        }

        std::sort(strs.begin(), strs.end());

        std::string first = strs[0];
        std::string last = strs[strs.size() - 1];
        std::string ans = "";

        for (int i = 0; i < first.length(); i++) {
            if (first[i] != last[i]) {
                break;
            }
            ans += first[i];
        }

        return ans;
    }
};

int main() {
    Solution solution;
    std::vector<std::string> strs = {"flower", "flow", "flight"};
    std::string result = solution.longestCommonPrefix(strs);
    std::cout << result << std::endl; // Output: "fl"
    return 0;
}
```

This example demonstrates a solution to the problem of finding the longest common prefix among a set of strings.

