class Solution {
public:
    vector<int> plusOne(vector<int>& digits) {
        int n = digits.size();
        digits[n - 1]++; // Increment the last digit

        for (int i = n - 1; i > 0; i--) {
            if (digits[i] > 9) {
                digits[i] %= 10; // Set the current digit to 0
                digits[i - 1]++; // Increment the previous digit
            }
        }

        if (digits[0] > 9) {
            digits.insert(digits.begin(), 1); // Insert 1 at the beginning
            digits[1] %= 10; // Set the second digit to 0
        }

        return digits;
    }
};
