// 1. Find the maximum subarray sum
// Given an array of integers, find the contiguous subarray (containing at least one number) which has the largest sum and return its sum.

// Example:
// Input: [-2, 1, -3, 4, -1, 2, 1, -5, 4]
// Output: 6
// Explanation: The subarray [4, -1, 2, 1] has the largest sum = 6.

// Solution:
// We can solve this problem using Kadane's algorithm. The idea is to keep track of the maximum sum of the subarray ending at each index and update the overall maximum sum if necessary.

// Time complexity: O(n)
// Space complexity: O(1)

#include <iostream>
#include <vector>
using namespace std;

int maxSubarraySum(vector<int>& nums) {
    int maxSum = nums[0];
    int currentSum = nums[0];

    for (int i = 1; i < nums.size(); i++) {
        currentSum = max(nums[i], currentSum + nums[i]);
        maxSum = max(maxSum, currentSum);
    }

    return maxSum;
}

int main() {
    vector<int> nums = {-2, 1, -3, 4, -1, 2, 1, -5, 4};
    int result = maxSubarraySum(nums);
    cout << "Maximum subarray sum: " << result << endl;
    return 0;
}

// Explanation:
