class Solution {
public:
    int maxScore(vector<int>& cardPoints, int k) {
        int n = cardPoints.size();
        int totalSum = 0;
        for (int i = 0; i < n; i++) {
            totalSum += cardPoints[i];
        }

        int windowSum = 0;
        for (int i = 0; i < n - k; i++) {
            windowSum += cardPoints[i];
        }

        int maxScore = totalSum - windowSum;
        int left = 0;
        int right = n - k;

        while (right < n) {
            windowSum += cardPoints[right] - cardPoints[left];
            maxScore = max(maxScore, totalSum - windowSum);
            left++;
            right++;
        }

        return maxScore;
    }
};

