#include <vector>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    int longestWPI(std::vector<int>& hours) {
        std::unordered_map<int, int> mp;
        int k = 0, ans = 0;
        for (int i = 0; i < hours.size(); i++) {
            if (hours[i] > 8)
                k++;
            else
