package com.example.leetcode;

import java.util.ArrayList;
import java.util.List;

public class LeetCode {

    public static void main(String[] args) {
        // Example usage
        int[] nums = {1, 2, 3};
        List<List<Integer>> subsets = generateSubsets(nums);
        System.out.println(subsets);
    }

    public static List<List<Integer>> generateSubsets(int[] nums) {
        List<List<Integer>> subsets = new ArrayList<>();
        generateSubsetsHelper(nums, 0, new ArrayList<>(), subsets);
        return subsets;
    }

    private static void generateSubsetsHelper(int[] nums, int index, List<Integer> currentSubset, List<List<Integer>> subsets) {
        // Base case: add the current subset to the result
        subsets.add(new ArrayList<>(currentSubset));

        // Recursive case: generate subsets by including and excluding each element
        for (int i = index; i < nums.length; i++) {
            currentSubset.add(nums[i]);
            generateSubsetsHelper(nums, i + 1, currentSubset, subsets);
            currentSubset.remove(currentSubset.size() - 1);
        }
    }
}
