class Solution {
    public int maxNumberOfBalloons(String text) {
        final int[][] cache = new int[2][6];
        cache[0][0] = 97;  // a
        cache[0][1] = 98;  // b
        cache[0][2] = 99;  // l
        cache[0][3] = 108; // n
        cache[0][4] = 111; // o
        cache[0][5] = 110; // o

        // calculate letter frequencies
        for (char ch : text.toCharArray()) {
            final int intValue = ch;
            for (int i = 0; i < 6; i++) {
                if (intValue == cache[0][i]) {
                    cache[1][i]++;
                    break;
                }
            }
        }

        // l and o meet twice
        cache[1][2] /= 2;
        cache[1][4] /= 2;

        // find the bottleneck
        int min = Integer.MAX_VALUE;
        for (int frequency : cache[1]) {
            min = Math.min(min, frequency);
        }

        return min;
    }
}

