package medium;

import java.util.Arrays;

public class MinimumTimeToVisitAllPoints {
    public int minTimeToVisitAllPoints(int[][] points) {
        int time = 0;
        for (int i = 0; i < points.length - 1; i++) {
            int[] point1 = points[i];
            int[] point2 = points[i + 1];
            int xDiff = Math.abs(point1[0] - point2[0]);
            int yDiff = Math.abs(point1[1] - point2[1]);
            time += Math.max(xDiff, yDiff);
        }
        return time;
    }

    public static void main(String[] args) {
        MinimumTimeToVisitAllPoints solution = new MinimumTimeToVisitAllPoints();
        int[][] points = {{1, 1}, {3, 4}, {-1, 0}};
        int result = solution.minTimeToVisitAllPoints(points);
        System.out.println("Minimum time to visit all points: " + result);
    }
}
