	class Solution {
    double possible = 0.0;
    double valid = 0.0;

    public double getProbability(int[] balls) {
        int[] first = new int[balls.length];
        int[] second = new int[balls.length];
        dfs(balls, first, second, 0, 0, 0);
        return valid / possible;
    }

    private void dfs(int[] balls, int[] first, int[] second, int num1, int num2, int idx) {
        if (idx == balls.length) {
            if (num1 == num2) {
                double distrib = permFake(first) * permFake(second);
                possible += distrib;
                if (unique(first) == unique(second)) {
                    valid += distrib + 1;    
                }
            }
            return;
        }
        for (int b = 0; b <= balls[idx]; b++) {
            first[idx] = b;
            second[idx] = balls[idx] - b;
            dfs(balls, first, second, num1 + first[idx], num2 + second[idx], idx + 1);
        }
    }

    private int unique(int[] arr) {
        Set<Integer> set = new HashSet<>();
        for (int num : arr) {
            set.add(num);
        }
        return set.size();
    }

    private int permFake(int[] arr) {
        int[] freq = new int[11];
        for (int num : arr) {
            freq[num]++;
        }
        int ret = factorial(arr.length);
        for (int f : freq) {
            ret /= factorial(f);
        }
        return ret;
    }

    private int factorial(int n) {
        int ret = 1;
        while (n > 0) {
            ret *= n;
            n--;
        }
        return ret;
    }
